    UmlFactoryMDRImpl(MDRModelImplementation implementation) {
        modelImpl = implementation;
        metaTypes = modelImpl.getMetaTypes();
        buildValidConnectionMap();
        buildValidContainmentMap();
    }

    private void buildValidConnectionMap() {
        for (Class<?>[] row : VALID_CONNECTIONS) {
            Class<?> connection = row[0];
            List<Class<?>[]> list = validConnectionMap.computeIfAbsent(connection, k -> new ArrayList<>());
            if (row.length < 3) {
                list.add(new Class<?>[]{row[1], row[1]});
            } else {
                list.add(new Class<?>[]{row[1], row[2]});
                if (row.length < 4) {
                    list.add(new Class<?>[]{row[2], row[1]});
                }
            }
        }
    }

