        ChangeCommand cmd = new ChangeCommand(
                modelImpl, run, "Create the operation # owned by #");
        editingDomain.getCommandStack().execute(cmd);
        cmd.setObjects(run.getParams().get(0), cls);

        return (Operation) run.getParams().get(0);
