     *
     * @param modelElement the UML model element
     * @param bounds the desired bounds (may be null)
     * @return the created FigNodeModelElement or null if not applicable
     */
    private FigNodeModelElement createFigNode(Object modelElement, Rectangle bounds) {
        DiagramSettings settings = getDiagramSettings();

        if (Model.getFacade().isAActionState(modelElement)) {
            return new FigActionState(modelElement, bounds, settings);
        }
        if (Model.getFacade().isAFinalState(modelElement)) {
            return new FigFinalState(modelElement, bounds, settings);
        }
        if (Model.getFacade().isAStubState(modelElement)) {
            return new FigStubState(modelElement, bounds, settings);
        }
        if (Model.getFacade().isASubmachineState(modelElement)) {
            return new FigSubmachineState(modelElement, bounds, settings);
        }
        if (Model.getFacade().isACompositeState(modelElement)) {
            return new FigCompositeState(modelElement, bounds, settings);
        }
        if (Model.getFacade().isASynchState(modelElement)) {
            return new FigSynchState(modelElement, bounds, settings);
        }
        if (Model.getFacade().isAState(modelElement)) {
            return new FigSimpleState(modelElement, bounds, settings);
        }
        if (Model.getFacade().isAComment(modelElement)) {
            return new FigComment(modelElement, bounds, settings);
        }
        if (Model.getFacade().isAPseudostate(modelElement)) {
            return createFigForPseudostate(modelElement, bounds);
        }
        LOG.log(Level.FINE, "Dropped object NOT added {0}", null);
        return null;
    }

    /**
     * Creates a FigNodeModelElement for a pseudostate based on its kind.
     *
     * @param pseudostate the UML pseudostate element
     * @param bounds the desired bounds (may be null)
     * @return the created FigNodeModelElement or null if kind unknown
     */
    private FigNodeModelElement createFigForPseudostate(Object pseudostate, Rectangle bounds) {
        DiagramSettings settings = getDiagramSettings();
        Object kind = Model.getFacade().getKind(pseudostate);
        if (kind == null) {
            LOG.log(Level.WARNING, "found a null type pseudostate");
            return null;
        }
        if (kind.equals(Model.getPseudostateKind().getInitial())) {
            return new FigInitialState(pseudostate, bounds, settings);
        }
        if (kind.equals(Model.getPseudostateKind().getChoice())) {
            return new FigBranchState(pseudostate, bounds, settings);
        }
        if (kind.equals(Model.getPseudostateKind().getJunction())) {
            return new FigJunctionState(pseudostate, bounds, settings);
        }
        if (kind.equals(Model.getPseudostateKind().getFork())) {
            return new FigForkState(pseudostate, bounds, settings);
        }
        if (kind.equals(Model.getPseudostateKind().getJoin())) {
            return new FigJoinState(pseudostate, bounds, settings);
        }
        if (kind.equals(Model.getPseudostateKind().getShallowHistory())) {
            return new FigShallowHistoryState(pseudostate, bounds, settings);
        }
        if (kind.equals(Model.getPseudostateKind().getDeepHistory())) {
            return new FigDeepHistoryState(pseudostate, bounds, settings);
        }
        LOG.log(Level.WARNING, "found a type not known");
        return null;
    }

    /**
     * Logs the creation of a FigNodeModelElement.
     *
     * @param source the source model element
     * @param figNode the created figure (may be null)
     */
    private void logFigCreation(Object source, FigNodeModelElement figNode) {
        if (figNode != null) {
            LOG.log(Level.FINE,
                    "Model element {0} converted to {1}",
                    new Object[]{source, figNode});
        } else {
            LOG.log(Level.FINE, "Dropped object NOT added {0}", figNode);
        }
    }

