def api(f):
    """Mark function as cache API."""
    f.is_cache_api = True
    return f


def read_api(f):
    """Mark function as read API."""
    f = api(f)
    f.is_read_api = True
    return f


def write_api(f):
    """Mark function as write API."""
    f = api(f)
    f.is_read_api = False
    return f


def wrap_simple(lock, func):
    @wraps(func)
    def call_func_with_lock(*args, **kwargs):
        try:
            with lock:
                return func(*args, **kwargs)
        except DowngradeLockError:
            return func(*args, **kwargs)
    return call_func_with_lock


def _is_seekable(obj):
    """Return True if object supports seek."""
    return hasattr(obj, 'seek')


def run_import_plugins(path_or_stream, fmt):
    """Run import plugins on a file or stream."""
    fmt = fmt.lower()
    if not _is_seekable(path_or_stream):
        return run_plugins_on_import(path_or_stream, fmt)

    path_or_stream.seek(0)
    pt = PersistentTemporaryFile('_import_plugin.' + fmt)
    shutil.copyfileobj(path_or_stream, pt, 1024 ** 2)
    pt.close()
    return run_plugins_on_import(pt.name, fmt)


