def api(f):
    f.is_cache_api = True
    return f


def read_api(f):
    f = api(f)
    f.is_read_api = True
    return f


def write_api(f):
    f = api(f)
    f.is_read_api = False
    return f


def wrap_simple(lock, func):
    @wraps(func)
    def call_func_with_lock(*args, **kwargs):
        try:
            with lock:
                return func(*args, **kwargs)
        except DowngradeLockError:
            # We already have an exclusive lock, no need to acquire a shared
            # lock. See the safe_read_lock properties' documentation for why
            # this is necessary.
            return func(*args, **kwargs)
    return call_func_with_lock


def _has_seek_method(obj):
    """Return True if *obj* provides a ``seek`` method."""
    return hasattr(obj, 'seek')


def _copy_stream_to_temp(stream, fmt):
    """Copy *stream* to a temporary file and return its filesystem path.

    The stream is rewound to the start before copying.
    """
    stream.seek(0)
    with PersistentTemporaryFile('_import_plugin.' + fmt) as pt:
        shutil.copyfileobj(stream, pt, 1024 ** 2)
        return pt.name


def run_import_plugins(path_or_stream, fmt):
    """Run import plugins on *path_or_stream* for the given format.

    If *path_or_stream* is a file‑like object, it is copied to a temporary
    file before the plugins are invoked.
    """
    fmt = fmt.lower()
    if not _has_seek_method(path_or_stream):
        return run_plugins_on_import(path_or_stream, fmt)

    path = _copy_stream_to_temp(path_or_stream, fmt)
    return run_plugins_on_import(path, fmt)


