    for x in refines[e.get('id')]:
        x.getparent().remove(x)
    refines.pop(e.get('id'), None)


def remove_element(e, refines):
    remove_refines(e, refines)
    e.getparent().remove(e)


def properties_for_id(item_id, refines):
    ans = {}
    if item_id:
        for elem in refines[item_id]:
            key = elem.get('property')
            if key:
                val = (elem.text or '').strip()
                if val:
                    ans[key] = val
    return ans


def _extract_scheme(scheme, prefixes):
    """Return (scheme_namespace, scheme) tuple.

    If *scheme* contains a known prefix, the namespace is looked up in *prefixes*
    and the prefix is stripped from the scheme. Otherwise the original scheme
    is returned with a ``None`` namespace.
    """
    if scheme is None:
        return None, None
    p, r = scheme.partition(':')[::2]
    if p and r:
        ns = prefixes.get(p)
        if ns:
            return ns, r
    return None, scheme


def properties_for_id_with_scheme(item_id, prefixes, refines):
    """Return a dict mapping property names to (scheme_ns, scheme, value)."""
    if not item_id:
        return {}
    ans = {}
    for elem in refines.get(item_id, []):
        key = elem.get('property')
        if not key:
            continue
        val = (elem.text or '').strip()
        if not val:
            continue
        scheme = elem.get('scheme')
        scheme_ns, scheme = _extract_scheme(scheme, prefixes) if scheme is not None else (None, None)
        ans[key] = (scheme_ns, scheme, val)
    return ans


def getroot(elem):
    while True:
        q = elem.getparent()
        if q is None:
            return elem
        elem = q


def ensure_id(elem):
    root = getroot(elem)
    eid = elem.get('id')
    if not eid:
        eid = ensure_unique('id', frozenset(XPath('//*/@id')(root)))
        elem.set('id', eid)
    return eid


def normalize_whitespace(text):
    if not text:
        return text
    return re.sub(r'\s+', ' ', text).strip()


def simple_text(f):
    @wraps(f)
    def wrapper(*args, **kw):
        return normalize_whitespace(f(*args, **kw))
    return wrapper


def items_with_property(root, q, prefixes=None):
    if prefixes is None:
        prefixes = read_prefixes(root)
    q = expand_prefix(q, known_prefixes).lower()
    for item in XPath("./opf:manifest/opf:item[@properties]")(root):
        for prop in (item.get('properties') or '').lower().split():
            prop = expand_prefix(prop, prefixes)
            if prop == q:
                yield item
                break

